import { useCallback } from 'react';
import {
  ReactFlow,
  addEdge,
  useNodesState,
  useEdgesState,
  Background,
  Controls,
  MiniMap
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import FiberDeviceNode from './FiberDeviceNode';

const nodeTypes = { fiberDevice: FiberDeviceNode };

export default function NetworkFlow({ onElementSelect, nodes, setNodes, edges, setEdges }) {
  const onConnect = useCallback(
    (params) => {
      const newEdge = {
        ...params,
        id: `edge-${params.source}-${params.target}-${Date.now()}`,
        label: 'Fiber Link',
        animated: true,
        style: { stroke: '#64748b', strokeWidth: 2 }
      };
      setEdges((eds) => addEdge(newEdge, eds));
    },
    [setEdges]
  );

  const onDragOver = useCallback((event) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
  }, []);

  // Simplified drop handler without useReactFlow
  const onDrop = useCallback(
    (event) => {
      event.preventDefault();
      const type = event.dataTransfer.getData('application/reactflow');
      if (!type) return;

      // Get canvas bounding rect for approximate positioning
      const reactFlowWrapper = event.currentTarget;
      const bounds = reactFlowWrapper.getBoundingClientRect();
      
      const position = {
        x: event.clientX - bounds.left,
        y: event.clientY - bounds.top,
      };

      const newNode = {
        id: `${type}-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
        type: 'fiberDevice',
        position,
        data: { type, hostname: '', ip: '' },
      };
      setNodes((nds) => [...nds, newNode]);
    },
    [setNodes]
  );

  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      onNodesChange={() => {}}
      onEdgesChange={() => {}}
      onConnect={onConnect}
      onDragOver={onDragOver}
      onDrop={onDrop}
      onNodeClick={(_, node) => onElementSelect({ type: 'node', id: node.id })}
      onEdgeClick={(_, edge) => onElementSelect({ type: 'edge', id: edge.id })}
      onPaneClick={() => onElementSelect(null)}
      nodeTypes={nodeTypes}
      fitView
      className="react-flow-container"
    >
      <Background color="#e2e8f0" gap={24} size={1} />
      <Controls />
      <MiniMap />
    </ReactFlow>
  );
}
